  <body>
    <script>
      // Surface anything that goes wrong while the modules are still evaluating.
      window.vhBootError = null;
      window.addEventListener('error', function (event) {
        var error = event.error;
        window.vhBootError = (error && (error.stack || error.message)) || event.message || 'unknown';
      });
      window.addEventListener('unhandledrejection', function (event) {
        var reason = event.reason;
        window.vhBootError = 'rejection: ' + ((reason && (reason.stack || reason.message)) || String(reason));
