  for (let ty = 32; ty <= 38; ty += 1) {
    for (let tx = 43; tx <= 49; tx += 1) {
      const dx = (tx - 46) / 3.1;
      const dy = (ty - 35) / 2.5;
      if (dx * dx + dy * dy < 1) paint(tx, ty, TERRAIN.WATER);
