  for (const roadCol of ROAD_COLS) {
    for (let ty = 0; ty < rows; ty += 1) {
      for (let span = 0; span < ROAD_SPAN; span += 1) {
        if (terrain[TILE_INDEX(roadCol + span, ty)] !== TERRAIN.WATER) paint(roadCol + span, ty, TERRAIN.ASPHALT);
      }
