        (dry(tx + 1, ty) && terrain[TILE_INDEX(tx + 1, ty)] === TERRAIN.ASPHALT) ||
        (dry(tx, ty - 1) && terrain[TILE_INDEX(tx, ty - 1)] === TERRAIN.ASPHALT) ||
