      }
      if (wet) continue;
      const districtId = districtForTile(Math.floor((tx0 + tx1) / 2), Math.floor((ty0 + ty1) / 2));
      blocks.push({
        i,
        j,
        tx0,
        ty0,
        tx1,
        ty1,
        district: districtId,
        x: tx0 * TILE,
        y: ty0 * TILE,
        w: (tx1 - tx0 + 1) * TILE,
        h: (ty1 - ty0 + 1) * TILE,
        cx: ((tx0 + tx1 + 1) / 2) * TILE,
        cy: ((ty0 + ty1 + 1) / 2) * TILE,
        parking: parkingBlocks.some((p) => p.tx0 === tx0 && p.ty0 === ty0),
